<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Snake</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #090d16;
      --panel: #111827;
      --panel-border: #263247;
      --text: #f3f6fb;
      --muted: #94a3b8;
      --green: #4ade80;
      --green-dark: #16a34a;
      --red: #fb5260;
      --button: #1e293b;
      --button-hover: #334155;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      overflow: auto;
      background:
        radial-gradient(circle at top, #172036 0, transparent 42%),
        var(--bg);
      color: var(--text);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    main {
      width: max-content;
      min-width: 560px;
      margin: 28px;
      padding: 24px;
      text-align: center;
      background: rgba(17, 24, 39, 0.94);
      border: 1px solid var(--panel-border);
      border-radius: 20px;
      box-shadow: 0 24px 70px rgba(0, 0, 0, 0.45);
    }

    h1 {
      margin: 0;
      font-size: 2rem;
      letter-spacing: 0.08em;
    }

    .topbar {
      width: 520px;
      margin: 14px auto 12px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      color: var(--muted);
    }

    .score-box {
      color: var(--text);
      font-size: 1.1rem;
      font-weight: 700;
    }

    #score {
      display: inline-block;
      min-width: 2ch;
      color: var(--green);
      font-variant-numeric: tabular-nums;
    }

    #status {
      font-size: 0.95rem;
    }

    #snake {
      display: block;
      width: 520px;
      height: 520px;
      margin: 0 auto;
      background: #080d14;
      border: 2px solid #334155;
      border-radius: 12px;
      box-shadow:
        inset 0 0 36px rgba(0, 0, 0, 0.5),
        0 12px 30px rgba(0, 0, 0, 0.3);
    }

    .controls {
      display: flex;
      justify-content: center;
      gap: 10px;
      margin-top: 18px;
    }

    button {
      min-width: 100px;
      padding: 10px 18px;
      border: 1px solid #3a4860;
      border-radius: 9px;
      background: var(--button);
      color: var(--text);
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 120ms ease, background 120ms ease, border-color 120ms ease;
    }

    button:hover:not(:disabled) {
      background: var(--button-hover);
      border-color: #64748b;
      transform: translateY(-1px);
    }

    button:active:not(:disabled) {
      transform: translateY(1px);
    }

    button:focus-visible {
      outline: 3px solid rgba(74, 222, 128, 0.45);
      outline-offset: 2px;
    }

    button:disabled {
      cursor: not-allowed;
      opacity: 0.45;
    }

    #start {
      color: #d7ffe4;
      border-color: #237a45;
    }

    #reset {
      color: #ffdce0;
      border-color: #7f3440;
    }

    .hint {
      margin: 14px 0 0;
      color: var(--muted);
      font-size: 0.88rem;
    }
  </style>
</head>
<body>
  <main>
    <h1>SNAKE</h1>

    <div class="topbar">
      <div class="score-box">Score: <span id="score">0</span></div>
      <div id="status" aria-live="polite">Ready</div>
    </div>

    <canvas
      id="snake"
      width="600"
      height="600"
      aria-label="Snake game board"
    ></canvas>

    <div class="controls">
      <button id="start" type="button">Start</button>
      <button id="pause" type="button">Pause</button>
      <button id="reset" type="button">Reset</button>
    </div>

    <p class="hint">Use the arrow keys or WASD to steer.</p>
  </main>

  <script>
    (() => {
      "use strict";

      const W = 20;
      const H = 20;
      const TICK_MS = 105;

      const canvas = document.getElementById("snake");
      const ctx = canvas.getContext("2d");
      const scoreElement = document.getElementById("score");
      const statusElement = document.getElementById("status");
      const startButton = document.getElementById("start");
      const pauseButton = document.getElementById("pause");
      const resetButton = document.getElementById("reset");

      const CELL_W = canvas.width / W;
      const CELL_H = canvas.height / H;

      const vectors = {
        up: [0, -1],
        down: [0, 1],
        left: [-1, 0],
        right: [1, 0]
      };

      const opposite = {
        up: "down",
        down: "up",
        left: "right",
        right: "left"
      };

      let body = [];
      let foodPosition = [0, 0];
      let direction = "right";
      let nextDirection = "right";
      let turnQueued = false;
      let isAlive = true;
      let scoreValue = 0;
      let timer = null;
      let stateText = "Ready";

      function stopTimer() {
        if (timer !== null) {
          clearInterval(timer);
          timer = null;
        }
      }

      function isRunning() {
        return timer !== null;
      }

      function updateInterface() {
        scoreElement.textContent = String(scoreValue);
        statusElement.textContent = stateText;
        startButton.disabled = isRunning();
        pauseButton.disabled = !isRunning();
        startButton.textContent = isAlive ? "Start" : "Restart";
      }

      function roundedRect(x, y, width, height, radius) {
        const r = Math.min(radius, width / 2, height / 2);
        ctx.beginPath();
        ctx.moveTo(x + r, y);
        ctx.lineTo(x + width - r, y);
        ctx.quadraticCurveTo(x + width, y, x + width, y + r);
        ctx.lineTo(x + width, y + height - r);
        ctx.quadraticCurveTo(x + width, y + height, x + width - r, y + height);
        ctx.lineTo(x + r, y + height);
        ctx.quadraticCurveTo(x, y + height, x, y + height - r);
        ctx.lineTo(x, y + r);
        ctx.quadraticCurveTo(x, y, x + r, y);
        ctx.closePath();
      }

      function drawGrid() {
        ctx.fillStyle = "#080d14";
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        ctx.strokeStyle = "rgba(148, 163, 184, 0.075)";
        ctx.lineWidth = 1;

        for (let x = 1; x < W; x++) {
          const px = x * CELL_W + 0.5;
          ctx.beginPath();
          ctx.moveTo(px, 0);
          ctx.lineTo(px, canvas.height);
          ctx.stroke();
        }

        for (let y = 1; y < H; y++) {
          const py = y * CELL_H + 0.5;
          ctx.beginPath();
          ctx.moveTo(0, py);
          ctx.lineTo(canvas.width, py);
          ctx.stroke();
        }
      }

      function drawFood() {
        const [x, y] = foodPosition;
        if (x < 0 || x >= W || y < 0 || y >= H) return;

        const cx = (x + 0.5) * CELL_W;
        const cy = (y + 0.5) * CELL_H;
        const radius = Math.min(CELL_W, CELL_H) * 0.31;

        ctx.save();
        ctx.shadowColor = "rgba(251, 82, 96, 0.8)";
        ctx.shadowBlur = 14;
        ctx.fillStyle = "#fb5260";
        ctx.beginPath();
        ctx.arc(cx, cy, radius, 0, Math.PI * 2);
        ctx.fill();

        ctx.shadowBlur = 0;
        ctx.fillStyle = "#ff9aa3";
        ctx.beginPath();
        ctx.arc(cx - radius * 0.3, cy - radius * 0.35, radius * 0.22, 0, Math.PI * 2);
        ctx.fill();

        ctx.strokeStyle = "#75d66b";
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.moveTo(cx, cy - radius * 0.75);
        ctx.quadraticCurveTo(cx + radius * 0.2, cy - radius * 1.35, cx + radius * 0.65, cy - radius * 1.1);
        ctx.stroke();
        ctx.restore();
      }

      function drawSnake() {
        body.forEach(([x, y], index) => {
          const padding = index === 0 ? 2.5 : 3.5;
          const px = x * CELL_W + padding;
          const py = y * CELL_H + padding;
          const width = CELL_W - padding * 2;
          const height = CELL_H - padding * 2;

          ctx.save();
          if (index === 0) {
            ctx.shadowColor = "rgba(74, 222, 128, 0.55)";
            ctx.shadowBlur = 10;
            ctx.fillStyle = isAlive ? "#4ade80" : "#819489";
          } else {
            const brightness = Math.max(42, 67 - index * 1.1);
            ctx.fillStyle = isAlive
              ? `hsl(142 65% ${brightness}%)`
              : "#59665f";
          }

          roundedRect(px, py, width, height, index === 0 ? 8 : 6);
          ctx.fill();
          ctx.restore();
        });

        if (body.length === 0) return;

        const [headX, headY] = body[0];
        const cx = (headX + 0.5) * CELL_W;
        const cy = (headY + 0.5) * CELL_H;
        let eye1;
        let eye2;

        if (direction === "right") {
          eye1 = [cx + 6, cy - 6];
          eye2 = [cx + 6, cy + 6];
        } else if (direction === "left") {
          eye1 = [cx - 6, cy - 6];
          eye2 = [cx - 6, cy + 6];
        } else if (direction === "up") {
          eye1 = [cx - 6, cy - 6];
          eye2 = [cx + 6, cy - 6];
        } else {
          eye1 = [cx - 6, cy + 6];
          eye2 = [cx + 6, cy + 6];
        }

        ctx.fillStyle = "#07110b";
        for (const [ex, ey] of [eye1, eye2]) {
          ctx.beginPath();
          ctx.arc(ex, ey, 2.7, 0, Math.PI * 2);
          ctx.fill();
        }
      }

      function drawOverlay() {
        if (isAlive) return;

        ctx.fillStyle = "rgba(3, 7, 12, 0.62)";
        ctx.fillRect(0, canvas.height / 2 - 61, canvas.width, 122);

        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillStyle = "#f8fafc";
        ctx.font = "700 39px system-ui, sans-serif";
        ctx.fillText("GAME OVER", canvas.width / 2, canvas.height / 2 - 13);

        ctx.fillStyle = "#cbd5e1";
        ctx.font = "18px system-ui, sans-serif";
        ctx.fillText("Press Reset or Restart", canvas.width / 2, canvas.height / 2 + 30);
      }

      function draw() {
        drawGrid();
        drawFood();
        drawSnake();
        drawOverlay();
        updateInterface();
      }

      function cellOccupied(x, y) {
        return body.some(([sx, sy]) => sx === x && sy === y);
      }

      function placeRandomFood() {
        const free = [];

        for (let y = 0; y < H; y++) {
          for (let x = 0; x < W; x++) {
            if (!cellOccupied(x, y)) free.push([x, y]);
          }
        }

        if (free.length === 0) {
          foodPosition = [-1, -1];
          isAlive = false;
          stateText = "You win!";
          stopTimer();
          return;
        }

        foodPosition = free[Math.floor(Math.random() * free.length)].slice();
      }

      function resetGame() {
        stopTimer();
        const centerY = Math.floor(H / 2);
        const headX = Math.floor(W / 2);

        body = [
          [headX, centerY],
          [headX - 1, centerY],
          [headX - 2, centerY],
          [headX - 3, centerY]
        ];

        direction = "right";
        nextDirection = "right";
        turnQueued = false;
        isAlive = true;
        scoreValue = 0;
        stateText = "Ready";
        placeRandomFood();
        draw();
      }

      function setDirection(requestedDirection) {
        if (!Object.prototype.hasOwnProperty.call(vectors, requestedDirection)) return;
        if (!isAlive || turnQueued) return;
        if (requestedDirection === direction) return;
        if (opposite[requestedDirection] === direction) return;

        nextDirection = requestedDirection;
        turnQueued = true;
      }

      function tickGame() {
        if (!isAlive) {
          draw();
          return;
        }

        direction = nextDirection;
        turnQueued = false;

        const [dx, dy] = vectors[direction];
        const [headX, headY] = body[0];
        const newHead = [headX + dx, headY + dy];
        const [newX, newY] = newHead;

        if (newX < 0 || newX >= W || newY < 0 || newY >= H) {
          isAlive = false;
          stateText = "Game over — wall";
          stopTimer();
          draw();
          return;
        }

        const eating = newX === foodPosition[0] && newY === foodPosition[1];
        const collisionLength = eating ? body.length : body.length - 1;

        for (let i = 0; i < collisionLength; i++) {
          if (body[i][0] === newX && body[i][1] === newY) {
            isAlive = false;
            stateText = "Game over — collision";
            stopTimer();
            draw();
            return;
          }
        }

        body.unshift(newHead);

        if (eating) {
          scoreValue += 1;
          placeRandomFood();
        } else {
          body.pop();
        }

        if (stateText === "Ready") stateText = "Manual play";
        draw();
      }

      function startGame() {
        if (!isAlive) resetGame();
        if (timer !== null) return;

        stateText = "Playing";
        timer = setInterval(tickGame, TICK_MS);
        draw();
      }

      function pauseGame() {
        if (timer === null) return;
        stopTimer();
        if (isAlive) stateText = "Paused";
        draw();
      }

      function setFood(x, y) {
        const foodX = Math.trunc(Number(x));
        const foodY = Math.trunc(Number(y));

        if (
          Number.isFinite(foodX) &&
          Number.isFinite(foodY) &&
          foodX >= 0 &&
          foodX < W &&
          foodY >= 0 &&
          foodY < H
        ) {
          foodPosition = [foodX, foodY];
          draw();
        }
      }

      startButton.addEventListener("click", startGame);
      pauseButton.addEventListener("click", pauseGame);
      resetButton.addEventListener("click", resetGame);

      window.addEventListener("keydown", event => {
        const keyDirections = {
          ArrowUp: "up",
          ArrowDown: "down",
          ArrowLeft: "left",
          ArrowRight: "right",
          w: "up",
          W: "up",
          s: "down",
          S: "down",
          a: "left",
          A: "left",
          d: "right",
          D: "right"
        };

        const requested = keyDirections[event.key];
        if (!requested) return;

        event.preventDefault();
        setDirection(requested);
      }, { passive: false });

      window.game = {
        w: W,
        h: H,
        reset: resetGame,
        tick: tickGame,
        setDir: setDirection,
        setFood,
        snake: () => body.map(segment => segment.slice()),
        food: () => foodPosition.slice(),
        alive: () => isAlive,
        score: () => scoreValue
      };

      resetGame();
    })();
  </script>
</body>
</html>
